import { ConnectionStore } from "./connection.svelte";
import { problems } from "./problems.svelte.ts";
import { SyncStore } from "./sync.svelte";

/** Singleton for the connection target (central server / local node) and auth state. */
export const connection = new ConnectionStore();

/** Singleton for Client WS incremental sync. */
export const sync = new SyncStore(connection);

/**
 * Application startup initialization (called once from `+layout.svelte`).
 *
 * 1. If the URL has `?token=` (the tokenized URL generated by `fxg web`), log in
 *    with it and remove it from the query (so the token does not remain in history)
 * 2. Check the auth state via `GET /api/v1/system/info`
 * 3. If authenticated, start the Client WS (otherwise show the token dialog)
 */
export async function initApp(): Promise<void> {
  const urlToken = readUrlToken();
  if (urlToken !== null) {
    stripUrlToken();
    try {
      await loginAndStart(urlToken);
      return;
    } catch (error) {
      // An invalid URL token is expected (expired link); fall back to the
      // dialog. Report it so the user understands why the token was rejected.
      problems.report("login", error, "warning");
    }
  }
  await connection.probe();
  if (connection.authenticated) sync.start();
}

/** Read `?token=` from the URL (null when absent). */
function readUrlToken(): string | null {
  if (typeof location === "undefined") return null;
  const token = new URLSearchParams(location.search).get("token");
  return token !== null && token.trim() !== "" ? token.trim() : null;
}

/** Remove `?token=` from history (keep it out of the address bar / history). */
function stripUrlToken(): void {
  if (typeof history === "undefined" || typeof location === "undefined") return;
  const url = new URL(location.href);
  url.searchParams.delete("token");
  history.replaceState(null, "", `${url.pathname}${url.search}${url.hash}`);
}

/** Log in from the token input dialog and start syncing. */
export async function loginAndStart(token: string): Promise<void> {
  await connection.login(token);
  sync.restart();
}

/** Log out (stop syncing + invalidate the Cookie). */
export async function logoutAndStop(): Promise<void> {
  sync.stop();
  await connection.logout();
}
